import{_ as s,C as a,o as r,c as n,j as t,a as i,E as d,a2 as l}from"./chunks/framework.BxGh02fV.js";const k=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"title":"Introduction"},"headers":[],"relativePath":"en/guide/index.md","filePath":"en/guide/index.md"}'),h={name:"en/guide/index.md"};function c(p,e,f,g,u,m){const o=a("Capture");return r(),n("div",null,[e[0]||(e[0]=t("h1",{id:"introduction",tabindex:"-1"},[i("Introduction "),t("a",{class:"header-anchor",href:"#introduction","aria-label":'Permalink to "Introduction"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Effortless is a desktop application that takes a software project from idea to delivery along the OPALE pipe. This guide documents the standard edition, screen by screen. AI agents can do the same operations: the application is the human view of what agents do too.",-1)),d(o,{name:"dashboard",alt:"A workspace dashboard: current phase, active epic, story and task"}),e[2]||(e[2]=l('<h2 id="the-mental-model" tabindex="-1">The mental model <a class="header-anchor" href="#the-mental-model" aria-label="Permalink to &quot;The mental model&quot;">​</a></h2><p><strong>Workspace.</strong> A workspace is an Effortless project: a folder holding <code>.effortless/</code> (the data, in JSON) and <code>blueprints/</code> (the same information, rendered as Markdown). Each workspace opens in its own tab.</p><p><strong>Project → Epic → Story → Task.</strong> Work is split into four levels. An epic groups stories, a story groups tasks. Only one epic and one story are active at a time: that is where work is focused.</p><p><strong>The OPALE phases.</strong> A story goes through five phases:</p><ol><li><strong>O</strong>: analysis (Observer);</li><li><strong>P</strong>: framing (Positionner);</li><li><strong>A</strong>: specifications (Articuler);</li><li><strong>L</strong>: plan (Lancer);</li><li><strong>E</strong>: execution.</li></ol><p>A story of kind <code>fix</code> skips framing and starts directly in execution. To move to the next phase, the documents required by the current phase must exist.</p><p><strong>Evolutions.</strong> The evolution registry is the product&#39;s memory: anomalies, features, improvements, discoveries, tests. Each has an identifier (for example <code>26ANO335</code>), a criticality from 1 to 3 and a status. Evolutions can be grouped into a lot, then graduated into an epic.</p><p><strong>Decisions and questions.</strong> Decisions (DEC-xx) and open questions are recorded at the story or epic level.</p><p><strong>Humans and agents.</strong> An AI agent connects to the same engine through an MCP server, with verbs such as <code>effortless_status</code> or <code>effortless_story_start</code>. What the agent does shows up in the application, and the other way round.</p><div class="tip custom-block"><p class="custom-block-title">The recommended setup</p><p>Keep the app open, and work with a command-line agent — Claude Code, Codex or Antigravity — <strong>started from the project root</strong> (the folder that contains <code>effortless.json</code>). The VS Code integrated terminal, opened on the project folder, works too. See <a href="/Effortless/en/agent/#working-at-your-best-the-agent-opened-at-the-project-root">Working at your best</a>.</p></div><h2 id="how-the-guide-is-organized" tabindex="-1">How the guide is organized <a class="header-anchor" href="#how-the-guide-is-organized" aria-label="Permalink to &quot;How the guide is organized&quot;">​</a></h2><p>To get started:</p><ul><li><a href="/Effortless/en/guide/first-run.html">First launch</a>: the startup screen and the assistant that creates your profile.</li><li><a href="/Effortless/en/guide/setup.html">Choosing your setup</a>: the work mode and the code layout (modules, external repositories, shared sources), to decide before you start.</li><li><a href="/Effortless/en/guide/start.html">Open a workspace</a>: the picker, your entry point.</li><li><a href="/Effortless/en/guide/create.html">Creation assistant</a> and <a href="/Effortless/en/guide/adopt.html">Adopt an existing project</a>: the two guided flows to start a project.</li><li><a href="/Effortless/en/guide/window.html">Window, bars and tray</a>: tabs, theme, sidebar, shortcuts, and what happens when you close the window.</li></ul><p>Then the screens of a workspace, in the order of the sidebar:</p><ul><li><strong>Steering</strong>: <a href="/Effortless/en/guide/dashboard.html">Dashboard</a>.</li><li><strong>Backlog &amp; work</strong>: <a href="/Effortless/en/guide/backlog.html">Backlog</a> and <a href="/Effortless/en/guide/tasks.html">Tasks</a>.</li><li><strong>Framing &amp; knowledge</strong>: <a href="/Effortless/en/guide/knowledge.html">Knowledge</a>.</li><li><strong>Quality &amp; versioning</strong>: <a href="/Effortless/en/guide/drift.html">Drift</a>, <a href="/Effortless/en/guide/git.html">Git</a>, <a href="/Effortless/en/guide/release.html">Delivery</a> and <a href="/Effortless/en/guide/modules.html">Modules</a>.</li><li>At the bottom of the sidebar: <a href="/Effortless/en/guide/settings.html">Project settings</a> and <a href="/Effortless/en/guide/help.html">Help</a>.</li><li><a href="/Effortless/en/guide/preferences.html">Profile and preferences</a>: application settings, independent of any project.</li></ul><p>Each page describes what the screen shows, then what you can do on it. When an MCP verb matches, a &quot;With an AI agent&quot; section names it.</p>',16))])}const y=s(h,[["render",c]]);export{k as __pageData,y as default};
